# ==============================================================================# 052_SYSTEM_EVENT_BUS.py# ==============================================================================import sqlite3from pathlib import Pathfrom datetime import datetimeROOT = Path(__file__).resolve().parentDB = ROOT / "MISSION_CONTROL" / "database" / "mission_control.db"conn = sqlite3.connect(DB, timeout=30)conn.row_factory = sqlite3.Rowcur = conn.cursor()

cur.execute("PRAGMA journal_mode=WAL")
cur.execute("PRAGMA synchronous=NORMAL")
cur.execute("PRAGMA busy_timeout=30000")# ==============================================================================# EVENT STREAM# ==============================================================================cur.execute("""CREATE TABLE IF NOT EXISTS system_event_bus(    id INTEGER PRIMARY KEY AUTOINCREMENT,    created_at TEXT,    origin TEXT,    event_type TEXT,    event_name TEXT,    payload TEXT,    priority TEXT,    processed INTEGER DEFAULT 0)""")conn.commit()# ==============================================================================# EVENTOS GERADOS PELO MASTER# ==============================================================================cur.execute("""SELECTdecision,system_statusFROM master_controlORDER BY id DESCLIMIT 1""")master = cur.fetchone()if master:    events = [        (            "MASTER_CONTROL",            "SYSTEM",            master["decision"],            "{}",            "HIGH"        ),        (            "MASTER_CONTROL",            "STATUS",            master["system_status"],            "{}",            "NORMAL"        )    ]    for event in events:        cur.execute("""        INSERT INTO system_event_bus(            created_at,            origin,            event_type,            event_name,            payload,            priority        )        VALUES(?,?,?,?,?,?)        """,(            datetime.now().isoformat(),            event[0],            event[1],            event[2],            event[3],            event[4]        ))conn.commit()# ==============================================================================# DASHBOARD# ==============================================================================print("="*80)print("SYSTEM EVENT BUS")print("="*80)cur.execute("""SELECTpriority,origin,event_type,event_name,processedFROM system_event_busORDER BY id DESCLIMIT 20""")rows = cur.fetchall()for row in rows:    status = "YES" if row["processed"] else "NO"    print(        f"{row['priority']:<8}"        f"{row['origin']:<20}"        f"{row['event_type']:<12}"        f"{row['event_name']:<30}"        f"{status}"    )print("="*80)cur.execute("SELECT COUNT(*) FROM system_event_bus")print("EVENTOS:", cur.fetchone()[0])print("="*80)conn.close()

